    CancelZonalShiftOutput.add_member(:status, Smithy::Schema::Shapes::ShapeRef.new(shape: ZonalShiftStatus, location_name: 'status', traits: {"smithy.api#documentation" => "<p>A status for a zonal shift.</p> <p>The <code>Status</code> for a zonal shift can have one of the following values:</p> <ul> <li> <p> <b>ACTIVE:</b> The zonal shift has been started and is active.</p> </li> <li> <p> <b>EXPIRED:</b> The zonal shift has expired (the expiry time was exceeded).</p> </li> <li> <p> <b>CANCELED:</b> The zonal shift was canceled.</p> </li> </ul>", "smithy.api#required" => {}}))
