    StartZonalShiftOutput.add_member(:resource_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceIdentifier, location_name: 'resourceIdentifier', traits: {"smithy.api#documentation" => "<p>The identifier for the resource that Amazon Web Services shifts traffic for. The identifier is the Amazon Resource Name (ARN) for the resource.</p> <p>Amazon Application Recovery Controller currently supports enabling the following resources for zonal shift and zonal autoshift:</p> <ul> <li> <p> <a href=\"https://docs.aws.amazon.com/r53recovery/latest/dg/arc-zonal-shift.resource-types.ec2-auto-scaling-groups.html\">Amazon EC2 Auto Scaling groups</a> </p> </li> <li> <p> <a href=\"https://docs.aws.amazon.com/r53recovery/latest/dg/arc-zonal-shift.resource-types.eks.html\">Amazon Elastic Kubernetes Service</a> </p> </li> <li> <p> <a href=\"https://docs.aws.amazon.com/r53recovery/latest/dg/arc-zonal-shift.resource-types.app-load-balancers.html\">Application Load Balancer</a> </p> </li> <li> <p> <a href=\"https://docs.aws.amazon.com/r53recovery/latest/dg/arc-zonal-shift.resource-types.network-load-balancers.html\">Network Load Balancer</a> </p> </li> </ul>", "smithy.api#required" => {}}))
    StartZonalShiftOutput.add_member(:away_from, Smithy::Schema::Shapes::ShapeRef.new(shape: AvailabilityZone, location_name: 'awayFrom', traits: {"smithy.api#documentation" => "<p>The Availability Zone (for example, <code>use1-az1</code>) that traffic is moved away from for a resource when you start a zonal shift. Until the zonal shift expires or you cancel it, traffic for the resource is instead moved to other Availability Zones in the Amazon Web Services Region.</p>", "smithy.api#required" => {}}))
    StartZonalShiftOutput.add_member(:expiry_time, Smithy::Schema::Shapes::ShapeRef.new(shape: ExpiryTime, location_name: 'expiryTime', traits: {"smithy.api#documentation" => "<p>The expiry time (expiration time) for a customer-initiated zonal shift. A zonal shift is temporary and must be set to expire when you start the zonal shift. You can initially set a zonal shift to expire in a maximum of three days (72 hours). However, you can update a zonal shift to set a new expiration at any time. </p> <p>When you start a zonal shift, you specify how long you want it to be active, which ARC converts to an expiry time (expiration time). You can cancel a zonal shift when you're ready to restore traffic to the Availability Zone, or just wait for it to expire. Or you can update the zonal shift to specify another length of time to expire in.</p>", "smithy.api#required" => {}}))
    StartZonalShiftOutput.add_member(:start_time, Smithy::Schema::Shapes::ShapeRef.new(shape: StartTime, location_name: 'startTime', traits: {"smithy.api#documentation" => "<p>The time (UTC) when the zonal shift starts.</p>", "smithy.api#required" => {}}))
    StartZonalShiftOutput.add_member(:status, Smithy::Schema::Shapes::ShapeRef.new(shape: ZonalShiftStatus, location_name: 'status', traits: {"smithy.api#documentation" => "<p>A status for a zonal shift.</p> <p>The <code>Status</code> for a zonal shift can have one of the following values:</p> <ul> <li> <p> <b>ACTIVE:</b> The zonal shift has been started and is active.</p> </li> <li> <p> <b>EXPIRED:</b> The zonal shift has expired (the expiry time was exceeded).</p> </li> <li> <p> <b>CANCELED:</b> The zonal shift was canceled.</p> </li> </ul>", "smithy.api#required" => {}}))
    StartZonalShiftOutput.add_member(:comment, Smithy::Schema::Shapes::ShapeRef.new(shape: ZonalShiftComment, location_name: 'comment', traits: {"smithy.api#documentation" => "<p>A comment that you enter about the zonal shift. Only the latest comment is retained; no comment history is maintained. A new comment overwrites any existing comment string.</p>", "smithy.api#required" => {}}))
    StartZonalShiftOutput.type = Types::StartZonalShiftOutput
    StartZonalShiftRequest.add_member(:resource_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceIdentifier, location_name: 'resourceIdentifier', traits: {"smithy.api#documentation" => "<p>The identifier for the resource that Amazon Web Services shifts traffic for. The identifier is the Amazon Resource Name (ARN) for the resource.</p> <p>Amazon Application Recovery Controller currently supports enabling the following resources for zonal shift and zonal autoshift:</p> <ul> <li> <p> <a href=\"https://docs.aws.amazon.com/r53recovery/latest/dg/arc-zonal-shift.resource-types.ec2-auto-scaling-groups.html\">Amazon EC2 Auto Scaling groups</a> </p> </li> <li> <p> <a href=\"https://docs.aws.amazon.com/r53recovery/latest/dg/arc-zonal-shift.resource-types.eks.html\">Amazon Elastic Kubernetes Service</a> </p> </li> <li> <p> <a href=\"https://docs.aws.amazon.com/r53recovery/latest/dg/arc-zonal-shift.resource-types.app-load-balancers.html\">Application Load Balancer</a> </p> </li> <li> <p> <a href=\"https://docs.aws.amazon.com/r53recovery/latest/dg/arc-zonal-shift.resource-types.network-load-balancers.html\">Network Load Balancer</a> </p> </li> </ul>", "smithy.api#required" => {}}))
    StartZonalShiftRequest.add_member(:away_from, Smithy::Schema::Shapes::ShapeRef.new(shape: AvailabilityZone, location_name: 'awayFrom', traits: {"smithy.api#documentation" => "<p>The Availability Zone (for example, <code>use1-az1</code>) that traffic is moved away from for a resource when you start a zonal shift. Until the zonal shift expires or you cancel it, traffic for the resource is instead moved to other Availability Zones in the Amazon Web Services Region.</p>", "smithy.api#required" => {}}))
    StartZonalShiftRequest.add_member(:expires_in, Smithy::Schema::Shapes::ShapeRef.new(shape: ExpiresIn, location_name: 'expiresIn', traits: {"smithy.api#documentation" => "<p>The length of time that you want a zonal shift to be active, which ARC converts to an expiry time (expiration time). Zonal shifts are temporary. You can set a zonal shift to be active initially for up to three days (72 hours).</p> <p>If you want to still keep traffic away from an Availability Zone, you can update the zonal shift and set a new expiration. You can also cancel a zonal shift, before it expires, for example, if you're ready to restore traffic to the Availability Zone.</p> <p>To set a length of time for a zonal shift to be active, specify a whole number, and then one of the following, with no space:</p> <ul> <li> <p> <b>A lowercase letter m:</b> To specify that the value is in minutes.</p> </li> <li> <p> <b>A lowercase letter h:</b> To specify that the value is in hours.</p> </li> </ul> <p>For example: <code>20h</code> means the zonal shift expires in 20 hours. <code>120m</code> means the zonal shift expires in 120 minutes (2 hours).</p>", "smithy.api#required" => {}}))
    StartZonalShiftRequest.add_member(:comment, Smithy::Schema::Shapes::ShapeRef.new(shape: ZonalShiftComment, location_name: 'comment', traits: {"smithy.api#documentation" => "<p>A comment that you enter about the zonal shift. Only the latest comment is retained; no comment history is maintained. A new comment overwrites any existing comment string.</p>", "smithy.api#required" => {}}))
